import{_ as s,a0 as d,w as i,s as a,ao as u,I as r,x as n,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux基礎：如何在命令列中查看目錄的大小 | LCTT x X-CMD","titleTemplate":false,"description":"Linux基礎：如何在命令列中查看目錄的大小 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux基礎：如何在命令列中查看目錄的大小 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux基礎：如何在命令列中查看目錄的大小 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140711 Linux Basics--How To Find Size of Directory Commands","title":"Linux基礎：如何在命令列中查看目錄的大小","tag":"201407","desc":""},"relativePath":"201407/20140711 Linux Basics--How To Find Size of Directory Commands.md","filePath":"[post].md"}'),l={name:"201407/20140711 Linux Basics--How To Find Size of Directory Commands.md"};function m(g,t,c,x,T,f){const o=d("Link");return i(),a("div",null,[t[11]||(t[11]=u(`<h1 id="linux基礎-如何在命令列中查看目錄的大小" tabindex="-1">Linux基礎：如何在命令列中查看目錄的大小 <a class="header-anchor" href="#linux基礎-如何在命令列中查看目錄的大小" aria-label="Permalink to “Linux基礎：如何在命令列中查看目錄的大小”">​</a></h1><p>這是寫給Liunx新用户的一系列文章中的第一篇，在這系列文章我將會寫一些對新用户來説非常好用的<strong>Linux基礎命令</strong>。</p><p><strong>注意</strong>：本文的目標讀者是僅有小量甚至是沒有任何Linux命令列使用經驗的讀者。</p><blockquote><p>作為一個Linux的新用户，我怎樣可以在命令列終端中查看某個目錄的屬性？</p></blockquote><p>###要求###</p><p>唯一的要求是<strong>du</strong>命令列工具。du基本上是所有Linux發行版本默認提供的工具。用以下的命令來檢查你的系統中是否可以使用du命令：</p><pre><code>man du
</code></pre><p><strong>du</strong> 命令用於輸出文件的空間使用情況。</p><p>###使用du###</p><p>不帶任何參數的運行du命令會顯示當前工作目錄以及其子目錄的文件名和所佔用的空間大小(以字節為單位)。</p><pre><code>du
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-overview.png" alt=""></p><p>使用<strong>-h</strong>參數以對用户友好的方式輸出文件大小，即分別以<strong>K, M</strong>和<strong>G</strong>來表示<strong>Kb,Mb</strong>和<strong>Gb</strong></p><pre><code>du -h
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-h.png" alt=""></p><p>若想查看某個特定目錄的文件大小，則在du命令中指定要查看的目錄名，如下：</p><pre><code>du -h Mapmaker
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-h-mapmaker.png" alt=""></p><p>使用 <strong>-c</strong> 參數來查看目錄所佔用磁盤空間的總大小</p><pre><code>du -ch
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-ch.png" alt=""></p><p>使用 <strong>-s</strong> 參數只輸出指定目錄佔用空間的大小</p><pre><code>du -sh Mapmaker Sandbox
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-ch.png" alt=""></p><p>使用 man du 查看du命令更多參數的用法</p><pre><code>man du
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/man-du.png" alt=""></p><p>知道du命令更多的用法？請分享給我和其他人。</p><hr>`,29)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),e(o,{href:"http://www.unixmen.com/linux-basics-find-size-directory-commands/"},{default:p(()=>[...t[0]||(t[0]=[n("http://www.unixmen.com/linux-basics-find-size-directory-commands/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=n("譯者：",-1)),e(o,{href:"https://github.com/cvsher"},{default:p(()=>[...t[2]||(t[2]=[n("cvsher",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const h=s(l,[["render",m]]);export{C as __pageData,h as default};
